import re
from pathlib import Path
import tarfile
import tempfile

# Constants
PATTERN = r"(?<!Distillr)\\\\AcroTray\.exe"
DIRECTORY = r"C:\\SomeDir\\"

def task_func(directory=DIRECTORY, file_pattern=PATTERN):
    pattern = re.compile(file_pattern)
    dir_path = Path(directory)

    with tempfile.NamedTemporaryFile(suffix=".tar", delete=False) as tmp:
        tar_path = tmp.name

    with tarfile.open(tar_path, "w") as tar:
        if dir_path.is_dir():
            for file_path in dir_path.rglob("*"):
                if file_path.is_file():
                    path_str = str(file_path).replace("/", "\\")
                    escaped_path_str = path_str.replace("\\", "\\\\")

                    if pattern.search(path_str) or pattern.search(escaped_path_str):
                        tar.add(file_path, arcname=file_path.relative_to(dir_path))

    return tar_path
